interface Image { byte[] data(); }

class RealImage implements Image {
    RealImage() { System.out.println("loading"); }
    public byte[] data() { return new byte[0]; }
}

class LazyImage implements Image {
    private RealImage real;
    public byte[] data() {
        if (real == null) real = new RealImage();
        return real.data();
    }
}

Image img = new LazyImage();
System.out.println("created");
img.data();

interface Discount { int apply(int total); }

class NoDiscount implements Discount { public int apply(int t) { return t; } }
class TenPercent implements Discount { public int apply(int t) { return t - t / 10; } }

class Checkout {
    private Discount discount = new NoDiscount();
    void setDiscount(Discount d) { this.discount = d; }
    int total(int amount) { return discount.apply(amount); }
}

Checkout c = new Checkout();
c.setDiscount(new TenPercent());
System.out.println(c.total(200));

