class Subject {
    private final List<Consumer<String>> subscribers = new ArrayList<>();

    void subscribe(Consumer<String> s) { subscribers.add(s); }

    void change(String value) { subscribers.forEach(s -> s.accept(value)); }
}

Subject s = new Subject();
s.subscribe(v -> System.out.println("A:" + v));
s.subscribe(v -> System.out.println("B:" + v));
s.change("x");

interface Handler { boolean handle(String request); }

class AuthHandler implements Handler {
    public boolean handle(String r) {
        if (!r.startsWith("auth")) return false;
        System.out.println("auth handled");
        return true;
    }
}

class LogHandler implements Handler {
    public boolean handle(String r) {
        System.out.println("log handled");
        return true;
    }
}

List<Handler> chain = List.of(new AuthHandler(), new LogHandler());
for (Handler h : chain) {
    if (h.handle("auth:me")) break;
}

interface Notifier { void send(String msg); }

class Email implements Notifier {
    public void send(String m) { System.out.println("email:" + m); }
}

class WithPrefix implements Notifier {
    private final Notifier inner;
    WithPrefix(Notifier inner) { this.inner = inner; }
    public void send(String m) { inner.send("[app] " + m); }
}

class Registry {
    private static final Registry INSTANCE = new Registry();
    private Registry() {}
    static Registry getInstance() { return INSTANCE; }

    private final List<Notifier> subscribers = new ArrayList<>();
    void subscribe(Notifier n) { subscribers.add(n); }
    void publish(String m) { subscribers.forEach(n -> n.send(m)); }
}

Registry.getInstance().subscribe(new WithPrefix(new Email()));
Registry.getInstance().subscribe(new Email());
Registry.getInstance().publish("hi");

