interface Tax { int of(int amount); }

class Zero   implements Tax { public int of(int a) { return 0; } }
class Twenty implements Tax { public int of(int a) { return a / 5; } }

static Tax forCountry(String code) {
    return code.equals("EE") ? new Twenty() : new Zero();
}

class Invoice {
    private Tax tax = new Zero();
    void setTax(Tax t) { this.tax = t; }
    int total(int amount) { return amount + tax.of(amount); }
}

Invoice inv = new Invoice();
inv.setTax(forCountry("EE"));
System.out.println(inv.total(100));
